// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 warpTime, uint256 unlockTime, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(unlockTime < type(uint256).max - 1);
        vm.warp(warpTime);
        uint256 amount = 1;
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        uint256 nowTs = block.timestamp;
        uint256 expected = unlockTime > nowTs ? unlockTime : nowTs;
        (uint256 gotUnlock, ) = c.Acc(actor);
        assertTrue(gotUnlock == expected, "unlockTime must be max(_unlockTime, now)");
    }
}
